// LoadPurchaseItem loads the evidenceLink's PurchaseItem into the .R struct
func (os EvidenceLinkSlice) LoadPurchaseItem(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	purchaseItems, err := os.PurchaseItem(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.PurchaseItem = nil
		o.R.Loaded.PurchaseItem = true
	}
	for _, o := range os {
		if o == nil {
			continue
		}

		for _, rel := range purchaseItems {

			if !(o.PurchaseID == rel.PurchaseID) {
				continue
			}
			if !o.ItemID.Valid {
				continue
			}

			if !(o.ItemID.Valid && o.ItemID.V == rel.ID) {
				continue
			}

			rel.R.EvidenceLinks = append(rel.R.EvidenceLinks, o)

			o.R.PurchaseItem = rel
			break
		}
	}

	return nil
}

